const TIME_LIMIT: int = 1800;
const TH18_BALL: int = 416;
xformdef ACCEL(target: fx) { step_speed(target, 90); }
async sub shoot(kind: int) {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 16;
    var target: fx = 2.3fx;
    var rounds: int = 10;
    var interval: int = 34;
    if rank == 1 { n = 32; target = 3.6fx; }
    if rank == 2 { n = 48; target = 4fx; }
    if rank == 3 { n = 56; target = 4.3fx; }
    if kind == 1 {
        n = 6;
        if rank == 1 { n = 12; }
        if rank == 2 { n = 16; }
        if rank == 3 { n = 28; target = 4.2fx; }
    }
    if kind == 2 {
        n = 5; rounds = 40; interval = 17;
        if rank == 1 { n = 10; }
        if rank == 2 { n = 15; }
        if rank == 3 { n = 17; target = 4fx; }
    }
    sh_reset(0); sh_sprite(0, TH18_BALL, 2);
    sh_ring(0, 1); sh_aim(0, 0); sh_count(0, n, 1);
    sh_speed(0, 1fx, 0fx); sh_dist(0, -4fx);
    sh_xform(0, ACCEL(target));
    for i in 0..rounds {
        sh_angle(0, rand(65536) as angle, 3deg);
        sh_fire(0);
        wait(interval);
    }
}
async sub girl(kind: int) {
    set_invuln(65535); set_hurtbox(16fx); set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn shoot(kind);
    wait(400);
    move_speed(120, 2fx, EASE_QUAD_IN);
    loop { wait(600); }
}
async sub wave() {
    wait(120);
    _ = spawn_enemy(0fx, -24fx, 3000, 0, 0, 0, girl(0));
    wait(240);
    _ = spawn_enemy(-30fx, -24fx, 2000, 0, 0, 0, girl(1));
    _ = spawn_enemy(30fx, -24fx, 2000, 0, 0, 0, girl(1));
    wait(240);
    _ = spawn_enemy(-120fx, -24fx, 2000, 0, 0, 0, girl(2));
    _ = spawn_enemy(120fx, -24fx, 2000, 0, 0, 0, girl(2));
    loop { wait(600); }
}
async sub controller() {
    set_invuln(65535); set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0); wait_spell();
    loop { wait(600); }
}
sub main() { _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, controller); loop { wait(600); } }
